// PASSAGES_NEED(loadScript, そのゲームのフォルダ, [レベル]) で、そのレベルのチャンク(lvN.js)と読む画面の文(txN.js)を読み込む
function PASSAGES_FILL(lv,A){const L=PASSAGES.filter(p=>p.lv===lv);A.forEach((a,i)=>{if(L[i]){L[i].chunks=a.chunks;L[i].words=a.words}})}
function PASSAGES_NEED(load,base,lvs){const P=PASSAGES_NEED.p;return Promise.all([...new Set(lvs)].filter(l=>l>=1&&l<=3).map(l=>P[l]||(P[l]=load(base+"lv"+l+".js").then(()=>load(base+"tx"+l+".js")).catch(e=>{delete P[l];throw e}))))}
PASSAGES_NEED.p={};
function PASSAGES_HAS(lv){return !!PASSAGES.find(p=>p.lv===lv&&p.chunks.length)}
// 読む画面の文(LS_TEXTS)。txN.js が LS_ADD で足す。英語は PASSAGES のチャンクから組み立てる(同じ英語を2回持たない)
const LS_TEXTS={};
function LS_ADD(C){for(const k in C)Object.defineProperty(LS_TEXTS,k,{enumerable:true,configurable:true,get(){const p=PASSAGES.find(x=>x.id===k),W=[];p.chunks.forEach(c=>c.tk.forEach(t=>W.push(t[0]+t[1]+t[2])));let i=0;const t=C[k];const v=Object.assign({},t,{list:t.list.map(([s,ja])=>[s.split(' | ').map(u=>{const m=u.match(/^(.):([0-9/]+)=/);return m[1]+':'+m[2].split('/').map(n=>W.slice(i,i+=+n).join(' ')).join(' / ')+u.slice(m[0].length-1)}).join(' | '),ja])});Object.defineProperty(LS_TEXTS,k,{value:v,enumerable:true});return v}})}
